const entry = (title, intro, audience, points, prepare, note = '') => ({title, intro, audience, points, prepare, note});

export const serviceContent = {
  p1: entry('Una rete di supporto per la tua impresa',
    'Il tesseramento permette di entrare nella rete associativa Conflavoro e approfondire i servizi dedicati alle piccole e medie imprese. La proposta comprende rappresentanza datoriale, assistenza nei rapporti di lavoro, formazione e opportunità per lo sviluppo dell’attività.',
    'Imprenditori e piccole e medie imprese che cercano un riferimento per le esigenze aziendali e sindacali.',
    [['Assistenza sindacale', 'Supporto nella scelta dei contratti collettivi e nella gestione dei rapporti con i lavoratori e delle controversie.'], ['Sviluppo dell’impresa', 'Orientamento su credito, finanza agevolata, gestione dei costi e convenzioni della rete.'], ['Formazione e certificazioni', 'Percorsi da individuare in base al settore, alle competenze da sviluppare e alle esigenze di sicurezza e qualità.']],
    'Indica il settore dell’attività e quali servizi associativi ti interessano.',
    'Quota associativa, modalità di adesione e condizioni dei singoli servizi vengono approfondite con Conflavoro. La richiesta di contatto non attiva il tesseramento.'),
  p15: entry('Buoni pasto per la pausa pranzo e la spesa',
    'Ticket Restaurant® è la soluzione Edenred per mettere a disposizione buoni pasto utilizzabili nella rete di esercizi e servizi alimentari convenzionati. Il portale presenta formati digitali e cartacei, pensati per organizzare il beneficio in base alle abitudini dei destinatari.',
    'Aziende con dipendenti, liberi professionisti e ditte individuali interessati a valutare i buoni pasto.',
    [['Diverse occasioni di utilizzo', 'Pausa pranzo, spesa alimentare, take away e servizi online aderenti alla rete Edenred.'], ['Formati flessibili', 'App, carta ricaricabile e buono cartaceo, con disponibilità da concordare con il partner.'], ['Gestione delle spese', 'Una soluzione per organizzare il beneficio e semplificare la rendicontazione delle spese collegate.']],
    'Indica il numero di utilizzatori, il formato preferito e il valore dei buoni che vorresti valutare.',
    'Il trattamento fiscale dipende dal destinatario, dal formato e dalle regole applicabili: sarà verificato sul caso concreto.'),
  p40: entry('Dalla ricerca del candidato al suo inserimento',
    'e-work affianca l’azienda nella ricerca e selezione del personale, partendo dalla definizione del ruolo e delle competenze necessarie. Il percorso comprende preselezione, colloqui e supporto all’inserimento, con un’attenzione sia alle capacità tecniche sia al modo di lavorare della persona.',
    'Aziende che devono assumere nuove risorse e vogliono organizzare una ricerca mirata.',
    [['Profilo da ricercare', 'Analisi della posizione, delle competenze richieste e degli obiettivi dell’azienda.'], ['Selezione dei candidati', 'Ricerca attraverso la rete e il database del partner, valutazione iniziale e colloqui di approfondimento.'], ['Inserimento e seguito', 'Affiancamento nella fase di ingresso e monitoraggio successivo alla selezione.']],
    'Descrivi mansione, sede di lavoro, competenze richieste e tempi previsti per l’inserimento.'),
  p82: entry('Una tutela per affrontare le controversie',
    'DAS propone soluzioni assicurative di tutela legale dedicate all’attività d’impresa e alle professioni. Le offerte presentate riguardano l’assistenza nelle controversie e le spese legali, con ambiti differenti secondo il prodotto scelto e le condizioni di polizza.',
    'Imprese, associazioni, professionisti e figure manageriali che vogliono valutare una protezione legale per la propria attività.',
    [['Rapporti contrattuali', 'Soluzioni per controversie con clienti, fornitori e dipendenti, da valutare in base alla copertura.'], ['Attività professionale', 'Tutela dedicata ai professionisti, anche per procedimenti collegati al lavoro e richieste di risarcimento.'], ['Rischi specifici', 'Il catalogo comprende proposte per edilizia, circolazione aziendale, sicurezza, privacy e altre esigenze settoriali.']],
    'Indica attività svolta, rischi da proteggere ed eventuali coperture già presenti.',
    'Garanzie, esclusioni, massimali e operatività devono essere verificati nel preventivo e nei documenti di polizza.'),
  p83: entry('Protezione per la casa e la vita quotidiana',
    'La proposta Generali Insurance Partner presenta soluzioni della linea Immagina Adesso dedicate alla casa, alla salute e al benessere personale. Il contatto serve a individuare le esigenze di protezione e approfondire la combinazione di garanzie e servizi più adatta.',
    'Persone e famiglie interessate a valutare una copertura per l’abitazione, la salute e gli imprevisti quotidiani.',
    [['Casa', 'Protezione dell’abitazione e servizi di assistenza collegati agli imprevisti domestici.'], ['Salute e benessere', 'Soluzioni orientate a prevenzione, cure e servizi di supporto alla persona.'], ['Armonia', 'Una proposta dedicata alla protezione dagli imprevisti nella vita di tutti i giorni.']],
    'Descrivi l’ambito di interesse e le protezioni che vorresti approfondire.',
    'Prestazioni, limiti e costi dipendono dal prodotto e dalle condizioni di polizza proposte.'),
  p84: entry('Proteggere i beni e la continuità dell’attività',
    'Attività Protetta Sempre riunisce soluzioni assicurative Generali rivolte al commercio, alle piccole imprese e agli artigiani. L’offerta permette di valutare la protezione dei locali, del contenuto e della gestione dell’attività in relazione al settore in cui opera l’impresa.',
    'Negozi, ristoranti, bar, studi professionali, attività artigiane e PMI del settore manifatturiero, commerciale e dei servizi.',
    [['Commercio e professioni', 'Proposte per le esigenze di negozi, pubblici esercizi, studi e altre attività a contatto con il pubblico.'], ['Imprese e artigiani', 'Valutazione delle coperture per immobili, beni e gestione operativa delle piccole imprese.'], ['Soluzioni per le PMI', 'La linea Genera Impresa consente di approfondire una proposta collegata alle caratteristiche aziendali.']],
    'Indica il tipo di attività, i locali utilizzati e i beni che intendi proteggere.',
    'La copertura effettiva sarà definita dal partner nel preventivo e nei documenti contrattuali.'),
  p86: entry('Coperture per gli eventi catastrofali',
    'La proposta Generali Insurance Partner riguarda la protezione dei beni aziendali dai danni direttamente provocati da calamità naturali. Il partner approfondisce le caratteristiche dell’impresa e degli immobili per valutare le coperture applicabili.',
    'Imprese che devono valutare la protezione del proprio patrimonio dai rischi catastrofali.',
    [['Eventi da considerare', 'La scheda presenta coperture per sismi, alluvioni, inondazioni, esondazioni e frane.'], ['Beni aziendali', 'Gli ambiti indicati comprendono fabbricati, terreni, impianti, macchinari e attrezzature industriali o commerciali.'], ['Verifica della situazione', 'Il confronto con il partner aiuta a definire i beni da assicurare e l’adeguatezza della proposta.']],
    'Prepara una descrizione dei beni, della loro ubicazione e delle polizze già esistenti.',
    'Obblighi applicabili, garanzie, franchigie, massimali ed esclusioni vanno verificati con il partner sul caso concreto.'),
  p90: entry('Analisi dei rischi e confronto delle coperture',
    'Legal-Fin presenta un servizio di brokeraggio assicurativo indipendente: analizza i rischi dell’azienda, confronta le proposte del mercato e negozia le condizioni per conto del cliente. Il supporto comprende anche la gestione tecnica e legale delle esigenze connesse ai sinistri.',
    'Imprese e studi professionali che vogliono valutare coperture, fideiussioni e rischi aziendali con un consulente dedicato.',
    [['Analisi dell’impresa', 'Esame delle vulnerabilità e delle protezioni già presenti per individuare le esigenze effettive.'], ['Confronto e negoziazione', 'Valutazione di offerte assicurative e delle condizioni economiche e contrattuali.'], ['Ambiti di intervento', 'Fideiussioni, rischi catastrofali, cyber risk, tutela legale, responsabilità professionale e welfare.']],
    'Indica il rischio o la garanzia richiesta e se desideri una revisione delle polizze esistenti.'),
  p111: entry('Protezione informatica e formazione dei dipendenti',
    'L’offerta Kaspersky combina strumenti per proteggere dispositivi e sistemi aziendali con percorsi di formazione sulla sicurezza informatica. Il portale distingue la protezione degli endpoint, il monitoraggio gestito dagli specialisti e la preparazione delle persone all’uso corretto degli strumenti digitali.',
    'PMI e organizzazioni che devono proteggere i propri sistemi o rafforzare le competenze di sicurezza del personale.',
    [['Security Awareness', 'Formazione online continua per aiutare i dipendenti a riconoscere rischi e comportamenti insicuri.'], ['Next EDR Optimum', 'Protezione degli endpoint e strumenti di rilevamento e risposta alle minacce informatiche.'], ['Next MXDR Optimum', 'Monitoraggio dell’infrastruttura e supporto degli specialisti nella valutazione degli allarmi e negli interventi.']],
    'Indica numero di dispositivi, sistemi utilizzati e presenza di un referente informatico.'),
  p2: entry('Supporto nei rapporti sindacali e contrattuali',
    'Conflavoro offre assistenza datoriale per affrontare la scelta del contratto collettivo, le relazioni con i lavoratori e le controversie. Il servizio unisce consulenza operativa e aggiornamento sui temi del lavoro, con un percorso da definire sulle esigenze dell’impresa.',
    'Aziende, imprenditori e professionisti che seguono la gestione contrattuale e sindacale del personale.',
    [['Scelta del CCNL', 'Analisi degli istituti contrattuali e supporto alla valutazione del contratto collettivo più adatto.'], ['Conciliazioni', 'Affiancamento nelle vertenze individuali e collettive e nella fase che precede il contenzioso.'], ['Accordi e aggiornamento', 'Approfondimenti su accordi di secondo livello e di prossimità, con aggiornamento per HR, consulenti e imprenditori.']],
    'Descrivi il settore, il CCNL applicato e la questione su cui desideri assistenza.'),
  p23: entry('Assistenza durante la vita della società',
    'Il servizio di diritto societario affianca l’impresa dalla costituzione alle successive scelte organizzative e operazioni straordinarie. I professionisti della rete approfondiscono gli aspetti legali della struttura societaria e dei rapporti tra soci e organi di gestione.',
    'Società in costituzione o già operative che devono affrontare cambiamenti, decisioni di governance o questioni tra soci.',
    [['Costituzione e modifiche', 'Consulenza sulla forma societaria, atti costitutivi e statuti, oltre a fusioni, scissioni e trasformazioni.'], ['Governance', 'Supporto per assemblee, consigli di amministrazione, regolamenti interni e patti parasociali.'], ['Conformità e responsabilità', 'Verifica delle esigenze normative e approfondimenti sulla responsabilità degli amministratori.']],
    'Indica la forma della società e la decisione o il problema da approfondire.'),
  p22: entry('Assistenza legale nella gestione del personale',
    'Conflavoro presenta un servizio di assistenza legale in diritto del lavoro per aiutare le imprese ad affrontare le questioni connesse ai rapporti con i lavoratori. Il confronto con il professionista serve a chiarire il problema, valutare i rischi e definire il supporto necessario.',
    'Datori di lavoro e imprese che cercano assistenza su una questione lavorativa o sindacale.',
    [['Rapporti di lavoro', 'Approfondimento delle esigenze legate ai contratti e alla gestione dei rapporti con il personale.'], ['Questioni sindacali', 'Valutazione del supporto richiesto in presenza di controversie o temi di diritto sindacale.'], ['Prevenzione dei rischi', 'Assistenza per verificare la conformità delle scelte aziendali e affrontare le criticità normative.']],
    'Descrivi brevemente la questione e le eventuali scadenze; i documenti saranno richiesti durante l’approfondimento.'),
  p51: entry('Entrare nella rete dei Centri di Formazione CFPT',
    'UNASF Conflavoro propone un percorso per diventare Centro di Formazione CFPT ed erogare corsi sulla sicurezza sul lavoro. La rete mette a disposizione assistenza tecnica, strumenti digitali e supporto alla gestione delle attività formative.',
    'Centri di formazione e operatori interessati a sviluppare un’offerta formativa nell’ambito della sicurezza sul lavoro.',
    [['Gestione dei corsi', 'Strumenti per organizzare docenti, sedi e lezioni, dall’accreditamento del corso al monitoraggio della formazione.'], ['Modalità di erogazione', 'Supporto per percorsi in presenza, a distanza e misti, secondo le modalità applicabili al corso.'], ['Competenze dei formatori', 'Possibilità di approfondire i Registri Professionali Qualificati e i requisiti delle diverse figure.']],
    'Indica esperienza, corsi che vorresti erogare, docenti disponibili e sedi operative.',
    'L’adesione e l’erogazione dei corsi richiedono la verifica dei requisiti e delle condizioni con UNASF.'),
  p76: entry('Un percorso di audit per il sistema di gestione',
    'ITC CERT presenta un servizio di certificazione dei sistemi di gestione aziendali. Il percorso comprende la valutazione del sistema, gli audit previsti e le successive verifiche di sorveglianza, con lo schema da scegliere in funzione dell’attività e degli obiettivi dell’impresa.',
    'Organizzazioni che intendono certificare un sistema di gestione o approfondire gli schemi adatti al proprio settore.',
    [['Schemi disponibili', 'Qualità, ambiente, salute e sicurezza, sicurezza delle informazioni, alimentare, energia e anticorruzione.'], ['Fasi di valutazione', 'Pre-audit opzionale, audit di livello 1 e 2 e valutazione per il rilascio della certificazione.'], ['Mantenimento', 'Verifiche periodiche per valutare il mantenimento dei requisiti del sistema.']],
    'Indica la norma di interesse, il settore, le sedi e le eventuali certificazioni già ottenute.',
    'Campo di applicazione, accreditamenti pertinenti e requisiti richiesti dal tuo committente vanno confermati con il partner.'),
  p77: entry('Valutare caratteristiche e conformità del prodotto',
    'ITC CERT presenta servizi di certificazione e verifica dei prodotti, con percorsi diversi secondo la tipologia e i requisiti da dimostrare. L’offerta comprende aspetti prestazionali, di sicurezza e ambientali, oltre alla valutazione di dichiarazioni e caratteristiche nel settore alimentare.',
    'Produttori e imprese che vogliono documentare caratteristiche, prestazioni o requisiti dei propri prodotti.',
    [['Dichiarazioni ambientali', 'Approfondimenti su EPD, studi del ciclo di vita del prodotto e requisiti CAM.'], ['Prodotti alimentari', 'Verifica di etichette, dichiarazioni e schemi applicabili al prodotto agroalimentare.'], ['DPI e prodotti industriali', 'Valutazioni tecniche, prove e verifiche di sicurezza in relazione al prodotto e allo schema richiesto.']],
    'Descrivi il prodotto, il mercato di destinazione e il requisito o la dichiarazione che devi dimostrare.'),
  p81: entry('Sicurezza e tracciabilità dei prodotti venduti',
    'La proposta ITC CERT riguarda la sicurezza generale dei prodotti immessi sul mercato e le responsabilità lungo la filiera. Il portale richiama in particolare le esigenze dei venditori online e di chi commercializza prodotti attraverso piattaforme come Amazon.',
    'Imprese che producono, importano o vendono prodotti, comprese le attività di commercio elettronico.',
    [['Requisiti di sicurezza', 'Approfondimento dei requisiti applicabili alla tipologia di prodotto commercializzato.'], ['Tracciabilità', 'Valutazione delle informazioni e delle responsabilità nella catena di fornitura.'], ['Vendita online', 'Supporto per affrontare le esigenze di conformità collegate alla presenza del prodotto sui marketplace.']],
    'Indica il tipo di prodotto, il tuo ruolo nella filiera e i canali attraverso cui lo vendi.',
    'Il partner verificherà l’ambito applicabile e gli interventi necessari al prodotto specifico.'),
  p94: entry('Valutazione tecnica dei progetti di ricerca e innovazione',
    'Finply propone un percorso di analisi e supporto alla certificazione tecnica delle attività di ricerca, sviluppo, innovazione e design. Il servizio esamina il progetto e la documentazione per verificarne la qualificazione tecnica e predisporre un fascicolo coerente.',
    'Imprese con attività in corso o concluse che vogliono approfondire la certificabilità tecnica dei propri progetti.',
    [['Analisi delle attività', 'Esame del lavoro svolto e dei requisiti tecnici pertinenti al progetto.'], ['Documentazione', 'Raccolta delle informazioni e individuazione delle eventuali criticità del fascicolo.'], ['Percorso di certificazione', 'Affiancamento nella preparazione e nella gestione del procedimento con i soggetti competenti.']],
    'Indica gli anni interessati, l’attività svolta e se sono già stati utilizzati crediti d’imposta.',
    'La certificazione tecnica ha un ambito specifico: effetti, condizioni e aspetti fiscali vanno valutati con il partner.'),
  p54: entry('Organizzare i processi con un sistema qualità',
    'ISO PRO Services offre consulenza per implementare un sistema di gestione della qualità secondo ISO 9001. Il percorso parte dall’analisi dell’organizzazione e accompagna l’azienda nella definizione dei processi, nella formazione e nelle verifiche interne.',
    'Imprese che vogliono strutturare la gestione della qualità e prepararsi alla certificazione ISO 9001.',
    [['Analisi iniziale', 'Individuazione delle esigenze e dei processi da organizzare o migliorare.'], ['Implementazione e formazione', 'Supporto alla costruzione del sistema e alla preparazione delle persone coinvolte.'], ['Audit e mantenimento', 'Pianificazione delle verifiche interne e assistenza per monitorare l’efficacia del sistema nel tempo.']],
    'Descrivi attività, dimensione dell’organizzazione ed eventuali richieste di certificazione da parte dei clienti.'),
  p55: entry('Gestire gli aspetti ambientali dell’attività',
    'ISO PRO Services accompagna l’azienda nella costruzione di un sistema di gestione ambientale secondo ISO 14001. Il lavoro riguarda l’individuazione degli aspetti ambientali significativi e l’organizzazione di pratiche e controlli per migliorarne la gestione.',
    'Organizzazioni che vogliono affrontare in modo strutturato il proprio impatto ambientale e prepararsi alla certificazione.',
    [['Aspetti ambientali', 'Analisi delle attività e delle aree su cui intervenire per migliorare le prestazioni.'], ['Processi e persone', 'Definizione delle pratiche operative e formazione del personale coinvolto.'], ['Controllo nel tempo', 'Audit interni e monitoraggio del sistema per seguirne il miglioramento e il mantenimento.']],
    'Indica settore, sedi operative e principali esigenze ambientali dell’azienda.'),
  p56: entry('Un sistema per la salute e la sicurezza sul lavoro',
    'La consulenza ISO PRO Services supporta l’adozione di un sistema di gestione secondo ISO 45001. Il percorso organizza prevenzione, valutazione dei rischi e coinvolgimento dei lavoratori, accompagnando l’impresa nella preparazione e nel mantenimento del sistema.',
    'Organizzazioni che vogliono strutturare la gestione della salute e sicurezza e affrontare il percorso di certificazione.',
    [['Prevenzione', 'Identificazione delle esigenze di gestione dei rischi e delle misure preventive.'], ['Partecipazione', 'Formazione e coinvolgimento delle persone per rendere operative le procedure di sicurezza.'], ['Verifiche interne', 'Audit e valutazione periodica dei processi per individuare gli interventi di miglioramento.']],
    'Indica settore, numero di sedi, organizzazione della sicurezza e certificazioni già presenti.'),
  p57: entry('Proteggere le informazioni con un sistema organizzato',
    'ISO PRO Services affianca le imprese nell’implementazione di un Sistema di Gestione della Sicurezza delle Informazioni secondo ISO/IEC 27001. Il servizio collega analisi dei rischi, politiche di sicurezza, controlli e formazione del personale.',
    'Organizzazioni che gestiscono informazioni aziendali o dei clienti e vogliono prepararsi alla certificazione del proprio sistema.',
    [['Valutazione dei rischi', 'Analisi delle esigenze di protezione dei dati e delle informazioni trattate.'], ['Politiche e controlli', 'Progettazione e adozione di misure organizzative per gestire gli accessi e i rischi individuati.'], ['Formazione e continuità', 'Preparazione del personale e supporto al mantenimento delle misure nel tempo.']],
    'Descrivi i servizi erogati, i dati gestiti e il motivo per cui ti viene richiesta la certificazione.'),
  p19: entry('Valutare la qualificazione per i lavori pubblici',
    'SOA Consult presenta un percorso per ottenere l’attestazione SOA, collegata alla qualificazione delle imprese per l’esecuzione di lavori pubblici. La valutazione riguarda requisiti economici, tecnici e organizzativi e la documentazione che li dimostra.',
    'Imprese edili, impiantistiche e operatori che intendono qualificarsi per lavori e opere pubbliche.',
    [['Verifica dei requisiti', 'Analisi iniziale della situazione aziendale e delle qualificazioni da richiedere.'], ['Gestione documentale', 'Supporto nella raccolta e nell’organizzazione degli elementi necessari alla valutazione.'], ['Percorso di attestazione', 'Approfondimento dell’iter applicabile all’impresa e delle opportunità collegate alla qualificazione.']],
    'Indica i lavori svolti, le categorie di interesse e l’eventuale attestazione già posseduta.',
    'Categorie, classifiche e requisiti effettivi saranno verificati da SOA Consult.'),
  p5: entry('Esaminare e certificare i contratti',
    'EBIASP presenta una procedura di certificazione per contratti di lavoro, appalto e subappalto. La commissione esamina gli aspetti formali e sostanziali dell’accordo e la relativa documentazione, nell’ambito delle proprie competenze.',
    'Imprese e professionisti che devono valutare la certificazione di un contratto di lavoro o di appalto.',
    [['Esame del contratto', 'Verifica del contenuto e della coerenza dell’accordo rispetto alle disposizioni applicabili.'], ['Procedura documentata', 'Gestione dell’iter attraverso gli strumenti dedicati della commissione.'], ['Ambito nazionale', 'La scheda presenta una commissione con competenza su tutto il territorio nazionale.']],
    'Indica la tipologia di contratto, l’attività prevista e le eventuali scadenze.',
    'Necessità della certificazione, effetti e documenti richiesti saranno valutati sul contratto specifico.'),
  p53: entry('Individuare il percorso di gestione adatto all’impresa',
    'ISO PRO Services propone consulenza su sistemi di gestione e percorsi di certificazione in diversi ambiti aziendali. Il contatto iniziale permette di collegare l’obiettivo dell’impresa allo standard pertinente, distinguendo l’implementazione del sistema dalle successive verifiche.',
    'Aziende che cercano un percorso personalizzato per migliorare qualità, sicurezza, sostenibilità o organizzazione.',
    [['Ambiti specialistici', 'Sicurezza alimentare, dispositivi medici, energia, continuità operativa e altri settori indicati dal partner.'], ['Organizzazione dei processi', 'Supporto per adattare il percorso alle attività e alle dimensioni aziendali.'], ['Scelta dello standard', 'Approfondimento dei requisiti richiesti da clienti, committenti o specifiche opportunità di mercato.']],
    'Indica il risultato che ti serve ottenere e, se disponibile, il nome dello standard richiesto.',
    'Schema, campo di applicazione e possibilità di certificazione vanno confermati con il partner.'),
  p93: entry('Valutare gli incentivi per ricerca e innovazione',
    'Finply analizza i progetti di ricerca, sviluppo, innovazione e design per valutare le opportunità di credito d’imposta. L’attività comprende l’esame tecnico dei progetti, la verifica dei requisiti e la preparazione della documentazione a supporto delle spese.',
    'Imprese che sviluppano nuovi prodotti, processi o software oppure svolgono attività di innovazione e design.',
    [['Attività da esaminare', 'Analisi del progetto e del lavoro effettivamente svolto, con verifica della sua qualificazione.'], ['Costi collegati', 'Valutazione di personale, consulenze, materiali, software e attrezzature pertinenti al progetto.'], ['Fattibilità e fascicolo', 'La scheda prevede una stima preliminare gratuita e supporto alla raccolta dei dati e alla predisposizione documentale.']],
    'Indica gli anni del progetto, le attività realizzate e le principali voci di costo.',
    'Ammissibilità, beneficio e modalità di utilizzo dipendono dalla misura e dal periodo interessato.'),
  p95: entry('Valorizzare gli investimenti nei beni immateriali',
    'Il servizio Finply sul Patent Box esamina le attività di ricerca e sviluppo collegate ai beni immateriali dell’impresa. L’obiettivo è verificare la possibilità di applicare l’agevolazione e costruire la documentazione che collega attività, costi sostenuti e beni interessati.',
    'Imprese che sviluppano software protetto, brevetti industriali, disegni o modelli collegati alla propria attività di ricerca.',
    [['Verifica dei beni', 'Analisi dei beni immateriali e delle attività svolte per il loro sviluppo.'], ['Stima preliminare', 'Il portale presenta una valutazione iniziale gratuita della fattibilità del beneficio.'], ['Dossier tecnico', 'Affiancamento nella raccolta delle informazioni e nella preparazione del fascicolo della pratica.']],
    'Indica i beni immateriali coinvolti e gli investimenti di ricerca e sviluppo collegati.',
    'Requisiti, periodi agevolabili ed eventuale cumulo con altri incentivi devono essere verificati sul progetto.'),
  p96: entry('Pianificare gli incentivi per beni e tecnologie',
    'Finply propone assistenza per valutare gli incentivi collegati agli investimenti in beni strumentali e tecnologie avanzate. Il percorso parte dall’analisi dell’investimento e prosegue con la gestione delle procedure e della documentazione richiesta dalla misura applicabile.',
    'Imprese che intendono acquistare macchinari, software industriali o sistemi per la digitalizzazione e l’energia.',
    [['Analisi dell’investimento', 'Verifica tecnica dei beni e stima preliminare della fattibilità, presentata come gratuita dal partner.'], ['Pianificazione della pratica', 'Organizzazione di tempi, documenti e comunicazioni richiesti per il progetto.'], ['Coordinamento tecnico', 'Supporto nei rapporti con i professionisti coinvolti e nella predisposizione delle attestazioni necessarie.']],
    'Descrivi i beni da acquistare, lo stato dell’investimento e i tempi previsti.',
    'La misura utilizzabile e i suoi requisiti vanno confermati prima dell’investimento; la richiesta non assicura l’ottenimento di un incentivo.'),
  p60: entry('Sviluppare contatti commerciali nei mercati esteri',
    'Expandiamo mette in relazione le imprese italiane con export manager specializzati nello sviluppo dei mercati internazionali. La proposta punta a individuare professionisti con contatti pertinenti al prodotto e ai Paesi di interesse, per creare relazioni con buyer e distributori.',
    'Aziende italiane che vogliono avviare o rafforzare le vendite all’estero.',
    [['Abbinamento con gli export manager', 'Selezione del professionista in base al mercato e alle opportunità commerciali dell’impresa.'], ['Rete di contatti', 'Accesso a relazioni con buyer, distributori e interlocutori dei mercati esteri.'], ['Sviluppo commerciale', 'Il portale presenta un modello di remunerazione collegato ai risultati e occasioni di incontro professionale.']],
    'Indica prodotti, mercati già serviti e Paesi in cui vorresti sviluppare le vendite.',
    'Compensi, attività incluse e obiettivi saranno definiti con il partner; i risultati commerciali non sono garantiti.'),
  p61: entry('Dall’idea di investimento alla ricerca degli incentivi',
    'Ayming aiuta le imprese a valutare strumenti come contributi a fondo perduto, crediti d’imposta e finanziamenti agevolati in relazione ai propri investimenti. Il percorso parte da un colloquio con un consulente, che ricostruisce il profilo dell’azienda e le sue esigenze di sviluppo. La scheda presenta un’analisi di pre-fattibilità gratuita per individuare le opportunità pertinenti.',
    'Imprese che stanno pianificando investimenti, anche in macchinari, software, digitalizzazione ed efficienza energetica, e vogliono capire quali misure approfondire.',
    [['Analisi del progetto', 'Un consulente dedicato raccoglie i fabbisogni di investimento e li trasforma in un profilo utile alla ricerca degli incentivi.'], ['Ricerca e presentazione', 'Monitoraggio delle opportunità e supporto per bandi regionali, nazionali e crediti d’imposta, secondo i requisiti del progetto.'], ['Gestione e seguito', 'Piattaforma per documenti e aggiornamenti, incontri con il consulente e supporto anche nelle fasi successive alla presentazione.']],
    'Descrivi cosa vuoi acquistare o realizzare, dove opera l’impresa, l’investimento indicativo e i tempi previsti.',
    'Disponibilità dei bandi, ammissibilità e importi vengono verificati sul progetto. L’analisi preliminare e l’eventuale incarico successivo hanno modalità e condizioni da approfondire con Ayming.'),
  p28: entry('Valutare il credito per investimenti e liquidità',
    'Confeserfidi presenta soluzioni per aiutare le imprese ad accedere a risorse finanziarie attraverso garanzie e rapporti con istituti di credito e operatori finanziari. Il servizio considera sia le esigenze correnti sia i progetti di sviluppo a più lungo termine.',
    'Imprese del commercio, artigianato, industria, turismo, agricoltura e servizi che devono finanziare attività o investimenti.',
    [['Investimenti', 'Valutazione di prestiti, mutui e leasing in relazione al progetto aziendale.'], ['Gestione corrente', 'Approfondimenti su fidi, anticipo fatture e altre esigenze legate al capitale circolante.'], ['Assistenza alla richiesta', 'Analisi dell’impresa e supporto nelle pratiche per individuare una soluzione coerente con il fabbisogno.']],
    'Indica finalità, importo orientativo e tempi in cui ti servono le risorse.',
    'Concessione, garanzie, costi e condizioni dipendono dalla valutazione della richiesta.'),
  p43: entry('Garanzie per accompagnare la richiesta di finanziamento',
    'Il credito garantito Confeserfidi è rivolto alle imprese che cercano una garanzia a supporto di un finanziamento. Il partner esamina l’operazione e accompagna l’azienda nei rapporti e nelle pratiche necessarie per valutarne l’accesso.',
    'Imprese che devono sostenere investimenti, capitale circolante o progetti di sviluppo e vogliono approfondire il supporto di una garanzia.',
    [['Tipi di operazione', 'La proposta comprende garanzie collegate a prestiti ipotecari, chirografari e leasing.'], ['Valutazione del fabbisogno', 'La richiesta viene esaminata in relazione all’azienda, al settore e al progetto.'], ['Accompagnamento', 'Consulenza dedicata e assistenza alle procedure amministrative dell’operazione.']],
    'Specifica il finanziamento richiesto e se è già in corso un confronto con una banca.',
    'La garanzia e il finanziamento richiedono valutazioni specifiche e non sono automatici.'),
  p44: entry('Trasformare i crediti commerciali in risorse disponibili',
    'Confeserfidi presenta soluzioni di factoring per valutare l’anticipo dei crediti verso i clienti. Il servizio è pensato per migliorare la gestione del capitale circolante quando gli incassi arrivano dopo il momento in cui l’azienda deve sostenere le proprie spese.',
    'Imprese con fatture e crediti commerciali da incassare, soprattutto in presenza di termini di pagamento dilazionati.',
    [['Esame dei crediti', 'Valutazione dei crediti e delle caratteristiche dell’operazione proposta.'], ['Gestione dei flussi di cassa', 'Possibilità di anticipare gli incassi per organizzare le risorse dell’impresa.'], ['Soluzione personalizzata', 'Definizione delle condizioni in relazione al portafoglio crediti e alle esigenze aziendali.']],
    'Indica importo dei crediti, scadenze e tipologia dei clienti debitori.',
    'Ammissibilità dei crediti, anticipo, costi e ripartizione dei rischi saranno definiti dal partner.'),
  p45: entry('Garanzie per appalti, contributi e contratti',
    'Confeserfidi propone fideiussioni per operazioni nelle quali viene richiesta una garanzia a favore di un altro soggetto. La valutazione parte dalla finalità dell’operazione e dai requisiti indicati nel bando, nel contratto o nella richiesta del beneficiario.',
    'Imprese che partecipano a gare, richiedono contributi pubblici o assumono obbligazioni commerciali.',
    [['Appalti', 'Valutazione della garanzia richiesta per partecipare o dare esecuzione a un’operazione contrattuale.'], ['Contributi pubblici', 'Approfondimento delle fideiussioni collegate alle condizioni di un’agevolazione.'], ['Obbligazioni commerciali', 'Analisi delle esigenze di garanzia previste nei rapporti con altri operatori.']],
    'Indica beneficiario, importo, durata e termine entro cui la garanzia viene richiesta.',
    'Il rilascio è soggetto a istruttoria e alla verifica delle condizioni dell’operazione.'),
  p46: entry('Documentare la capacità finanziaria dell’impresa',
    'Confeserfidi offre un servizio per il rilascio di attestazioni di capacità finanziaria, sulla base dell’analisi dei dati economici e finanziari aziendali. Il documento può essere richiesto in contesti diversi e deve corrispondere alle esigenze dell’ente o del soggetto destinatario.',
    'Aziende a cui viene chiesta una dimostrazione della capacità finanziaria per gare, autorizzazioni o altre procedure.',
    [['Requisito richiesto', 'Verifica della finalità e delle caratteristiche dell’attestazione necessaria.'], ['Analisi dei dati', 'Esame delle informazioni economiche e finanziarie dell’impresa.'], ['Supporto documentale', 'Accompagnamento dalla raccolta dei documenti alla definizione dell’attestazione.']],
    'Allega successivamente al partner la richiesta ricevuta e segnala fin da ora la scadenza da rispettare.',
    'Rilascio e contenuto dipendono dall’esito della valutazione e dai requisiti della procedura.'),
  p20: entry('Individuare e gestire le agevolazioni per l’impresa',
    'Confeserfidi affianca l’azienda nella ricerca e nella gestione delle opportunità di finanza agevolata. La scheda comprende contributi pubblici e crediti d’imposta, con un’analisi delle esigenze per individuare le misure pertinenti e seguire la pratica nelle sue diverse fasi.',
    'Imprese che vogliono valutare bandi, incentivi e contributi in relazione ai propri progetti.',
    [['Ricerca delle opportunità', 'Monitoraggio dei bandi e degli incentivi da approfondire per l’impresa.'], ['Strategia delle agevolazioni', 'Analisi delle misure utilizzabili e delle possibilità di integrazione, quando consentite.'], ['Gestione della pratica', 'Assistenza dalla preparazione della richiesta fino alle fasi di completamento del progetto.']],
    'Descrivi l’attività, la sede dell’investimento e il progetto per cui cerchi un’agevolazione.',
    'Accesso, cumulabilità, disponibilità e importi dipendono dalle misure e dalla valutazione del progetto.'),
  p97: entry('Verificare le agevolazioni contributive non utilizzate',
    'Finply analizza la situazione contributiva del personale per individuare eventuali incentivi non richiesti e opportunità di risparmio. Il lavoro esamina i rapporti di lavoro e confronta i dati con le disposizioni applicabili ai periodi interessati.',
    'Aziende con dipendenti che vogliono verificare se la gestione contributiva ha tenuto conto delle agevolazioni disponibili.',
    [['Analisi dei rapporti', 'Esame di assunzioni, trasformazioni e cessazioni rilevanti per la verifica.'], ['Verifica dei dati', 'Utilizzo di competenze contributive e strumenti digitali per individuare gli elementi da approfondire.'], ['Procedure di recupero', 'Preparazione delle richieste attraverso i canali previsti e verifica dell’eventuale autorizzazione INPS.']],
    'Indica il numero di dipendenti e gli anni che vorresti sottoporre ad analisi.',
    'Importi recuperabili, termini e possibilità di utilizzo dei crediti dipendono dall’esito delle verifiche e delle procedure.'),
  p62: entry('Gestire gli adempimenti ambientali nei mercati serviti',
    'Ayming supporta le imprese nell’analisi dei tributi e dei contributi ambientali legati ai prodotti e ai Paesi in cui operano. Il percorso comprende la mappatura degli obblighi, la raccolta dei dati, i calcoli e il supporto agli adempimenti individuati.',
    'Imprese che producono, importano o commercializzano beni e materiali soggetti a obblighi ambientali in Italia o all’estero.',
    [['Ambiti da verificare', 'Imballaggi, plastica, tessili e altri prodotti indicati nella scheda del partner.'], ['Analisi per Paese', 'Mappatura delle disposizioni e del loro impatto economico e operativo.'], ['Gestione degli adempimenti', 'Report personalizzati, individuazione delle criticità e supporto operativo alla conformità.']],
    'Indica prodotti, materiali e Paesi in cui l’azienda commercializza o importa.',
    'Decorrenze e obblighi sono verificati in base al mercato e all’attività effettiva dell’impresa.'),
  p63: entry('Supporto fiscale per chi opera tra più Paesi',
    'Ayming presenta consulenza in materia di IVA e fiscalità internazionale per imprese già attive all’estero o che intendono espandersi. Il servizio comprende temi IVA, doganali e di transfer pricing, con assistenza anche nelle verifiche e nei contenziosi.',
    'Imprese e gruppi con operazioni internazionali, sedi estere o progetti di ingresso nel mercato italiano.',
    [['IVA', 'Valutazione di identificazione diretta, rappresentanza fiscale e recupero dell’IVA estera nei casi applicabili.'], ['Dogane', 'Consulenza su classificazione delle merci, origine, valore e regimi doganali.'], ['Fiscalità dei gruppi', 'Supporto su transfer pricing, documentazione e questioni legate all’operatività in più Stati.']],
    'Indica i Paesi coinvolti, le operazioni svolte e il problema o progetto da approfondire.'),
  p87: entry('Protezione assicurativa per le persone in azienda',
    'Welfare Imprese di Generali Insurance Partner è una proposta assicurativa dedicata alle esigenze di protezione del personale. La scheda del portale collega la valutazione dell’offerta al settore in cui opera l’azienda e alla sua dimensione.',
    'Aziende che vogliono approfondire strumenti assicurativi a beneficio dei propri collaboratori.',
    [['Esigenze del personale', 'Individuazione degli obiettivi di protezione che l’impresa desidera affrontare.'], ['Caratteristiche aziendali', 'Valutazione della proposta in relazione al settore e alla dimensione dell’organizzazione.'], ['Confronto sulla copertura', 'Approfondimento con il partner delle prestazioni effettivamente disponibili e delle condizioni.']],
    'Indica settore, numero di collaboratori e obiettivi del progetto di welfare.',
    'Prestazioni, destinatari, esclusioni e costi devono essere specificati nella proposta assicurativa.'),
  p48: entry('Progettare un piano welfare legato ai bisogni reali',
    'Conflavoro supporta l’organizzazione e la redazione di piani di welfare aziendale. Il percorso parte dalle esigenze dell’impresa e dei dipendenti per individuare benefici sostenibili e utili, definendo anche gli aspetti organizzativi e gli eventuali accordi necessari.',
    'Aziende che vogliono introdurre o rivedere un piano di beni e servizi per i lavoratori.',
    [['Analisi dei fabbisogni', 'Valutazione delle priorità delle persone e degli obiettivi dell’azienda.'], ['Piano personalizzato', 'Organizzazione dei benefici, anche legati alla famiglia e alla crescita professionale.'], ['Attuazione del piano', 'Supporto alla redazione e all’eventuale accordo sindacale, con attenzione alla comunicazione ai dipendenti.']],
    'Indica numero di dipendenti, budget orientativo e benefici già presenti.',
    'Il trattamento fiscale e le modalità di introduzione del piano vanno verificati sul caso concreto.'),
  p49: entry('Collegare il premio a obiettivi aziendali misurabili',
    'Conflavoro affianca l’impresa nell’elaborazione e nella stipula dell’accordo sindacale collegato a un premio di risultato. Il progetto parte dalla definizione degli obiettivi e dei parametri con cui misurarli, valutando i requisiti del trattamento applicabile.',
    'Aziende che intendono costruire un sistema di incentivazione legato ai risultati aziendali.',
    [['Obiettivi del premio', 'Individuazione di risultati legati a produttività, qualità o efficienza.'], ['Parametri di misurazione', 'Definizione di criteri chiari per verificare il raggiungimento degli obiettivi.'], ['Accordo sindacale', 'Supporto alla costruzione dell’accordo e alla verifica dei requisiti pertinenti.']],
    'Descrivi i risultati che vuoi premiare e l’organizzazione attuale del personale.',
    'Limiti, agevolazioni fiscali e contributive e condizioni di applicazione devono essere verificati per l’anno e il progetto interessati.'),
  p30: entry('Buoni acquisto per le esigenze quotidiane',
    'I Buoni Acquisto Edenred permettono di mettere a disposizione un beneficio utilizzabile presso i marchi e i canali aderenti. La proposta comprende diverse categorie di spesa e formati, così da adattare l’iniziativa alle esigenze dei destinatari.',
    'Aziende che vogliono valutare buoni acquisto e iniziative di benefit per i dipendenti.',
    [['Categorie di utilizzo', 'La rete comprende abbigliamento, elettronica, sport, libri, casa, tempo libero e altri acquisti.'], ['Formati disponibili', 'Il portale presenta app, voucher digitale e buono cartaceo.'], ['Acquisti anche online', 'Possibilità di utilizzo presso i canali aderenti, da verificare in base al buono e al marchio.']],
    'Indica numero di destinatari, valore indicativo e formato preferito.',
    'Soglie e trattamento fiscale dei benefit dipendono dalle condizioni applicabili e saranno verificati prima dell’attivazione.'),
  p31: entry('Una piattaforma per usare i servizi di welfare',
    'Edenred propone consulenza e strumenti digitali per realizzare un’offerta welfare su misura. I dipendenti possono accedere a beni e servizi attraverso una piattaforma, utilizzabile anche da app, mentre l’azienda definisce il progetto in base ai propri obiettivi.',
    'Aziende che vogliono introdurre servizi welfare e semplificarne l’accesso da parte dei dipendenti.',
    [['Consulenza dedicata', 'Supporto per collegare il piano alle esigenze dell’organizzazione e delle persone.'], ['Accesso digitale', 'Piattaforma e app per utilizzare i servizi e i benefici disponibili.'], ['Rete convenzionata', 'Strutture e canali aderenti per voucher welfare e buoni acquisto.']],
    'Indica dimensione dell’azienda, piano eventualmente già attivo e benefici da integrare.',
    'Servizi inclusi, costi e trattamento fiscale sono da definire con il partner.'),
  p58: entry('Veicoli commerciali a noleggio per il lavoro',
    'Bidrive propone noleggio a lungo termine di veicoli commerciali per le esigenze operative dell’impresa. Il consulente aiuta a scegliere il mezzo e la soluzione di gestione, approfondendo assistenza e manutenzione previste nell’offerta.',
    'Aziende e professionisti che utilizzano furgoni o altri veicoli commerciali e vogliono valutare una soluzione di noleggio.',
    [['Scelta del veicolo', 'Valutazione del mezzo in relazione all’attività e alle esigenze di utilizzo.'], ['Gestione della flotta', 'Soluzioni per organizzare i veicoli e i costi della mobilità aziendale.'], ['Assistenza e manutenzione', 'Servizi dedicati ai mezzi e supporto sul territorio, secondo il contratto proposto.']],
    'Indica numero di mezzi, utilizzo, percorrenza orientativa e durata desiderata.',
    'Canone, servizi inclusi, disponibilità, chilometraggio e condizioni verranno specificati nel preventivo.'),
  p59: entry('Noleggio auto per gli spostamenti di ogni giorno',
    'Bidrive offre noleggio a lungo termine di autovetture, con modelli e configurazioni da valutare in base all’utilizzo personale o professionale. La proposta presenta un canone che riunisce il veicolo e i servizi previsti dal contratto.',
    'Persone, professionisti e imprese che cercano un’auto a noleggio per spostamenti urbani o lunghe percorrenze.',
    [['Scelta del modello', 'Gamma di auto per esigenze diverse, con possibilità di approfondire configurazioni ed equipaggiamenti.'], ['Servizi nel canone', 'Valutazione di manutenzione, assistenza e servizi assicurativi inclusi nell’offerta.'], ['Alimentazioni', 'Il partner presenta anche veicoli ibridi ed elettrici.']],
    'Indica modello o categoria, chilometri annui, durata e budget orientativo.',
    'Le condizioni effettive, gli eventuali anticipi e i limiti dei servizi saranno indicati nel preventivo.'),
  p65: entry('Forniture di luce e gas per la casa',
    'Enerviva propone forniture domestiche di energia elettrica e gas con gestione digitale delle utenze. Il contatto permette di approfondire l’offerta rispetto alle esigenze della famiglia e alle caratteristiche della fornitura.',
    'Privati e famiglie che vogliono valutare una soluzione per le utenze domestiche.',
    [['Offerta da valutare', 'Confronto con il partner sulle caratteristiche della fornitura e sulle condizioni disponibili.'], ['Gestione digitale', 'Strumenti e app per consultare bollette e gestire i pagamenti.'], ['Assistenza', 'Un riferimento per richieste e necessità legate alla gestione dell’utenza.']],
    'Indica se ti interessano luce, gas o entrambe le utenze e il Comune della fornitura.',
    'Tariffe, condizioni contrattuali ed eventuale cambio di gestore saranno approfonditi prima dell’adesione.'),
  p66: entry('Luce e gas per le esigenze dell’impresa',
    'Enerviva presenta un’offerta di energia elettrica e gas dedicata alle attività economiche. Il servizio combina il confronto sulle esigenze della fornitura con strumenti digitali per la gestione di bollette e pagamenti.',
    'Imprese e attività professionali che vogliono valutare la fornitura energetica delle proprie sedi.',
    [['Esigenze aziendali', 'Valutazione della proposta in relazione all’attività e alle utenze interessate.'], ['Controllo delle bollette', 'Gestione digitale per organizzare la consultazione e il pagamento delle forniture.'], ['Rapporto con il gestore', 'Assistenza per le richieste legate al servizio e alle necessità dell’impresa.']],
    'Indica attività, numero di sedi e tipologia di utenze da valutare.',
    'La convenienza dipende dai consumi e dalle condizioni proposte: sarà verificata sull’offerta concreta.'),
  p67: entry('Valutare la produzione di energia solare',
    'La proposta Enerviva riguarda il fotovoltaico per abitazioni e attività aziendali. L’obiettivo è produrre energia da una fonte rinnovabile e valutare quanto l’impianto possa contribuire ai consumi dell’immobile e alla gestione della spesa energetica.',
    'Privati e imprese interessati a valutare un impianto fotovoltaico per la propria sede o abitazione.',
    [['Produzione di energia', 'Approfondimento di una soluzione per utilizzare l’energia solare nell’immobile.'], ['Consumi e costi', 'Valutazione del contributo dell’impianto alla riduzione dell’energia acquistata dalla rete.'], ['Progetto sostenibile', 'Un intervento da esaminare in relazione alle caratteristiche della struttura e agli obiettivi energetici.']],
    'Indica Comune, tipo di immobile e consumi indicativi.',
    'Fattibilità, risparmio e possibili agevolazioni richiedono una verifica del progetto; non sono risultati automatici.'),
  p79: entry('Un percorso assistito per l’assunzione di lavoratori stranieri',
    'Conflavoro presenta assistenza per le procedure di ingresso e assunzione attraverso il Decreto Flussi. Il servizio comprende l’esame dei requisiti aziendali, la preparazione della domanda e il seguito delle fasi necessarie all’inserimento del lavoratore.',
    'Imprese che vogliono valutare l’assunzione di lavoratori stranieri attraverso le procedure previste.',
    [['Verifica iniziale', 'Esame del settore, della situazione aziendale e dei requisiti pertinenti alla domanda.'], ['Preparazione e invio', 'Supporto alla documentazione e alla presentazione delle richieste attraverso i canali previsti.'], ['Fasi successive', 'Affiancamento nelle attività collegate a nulla osta, ingresso e avvio del rapporto di lavoro.']],
    'Indica settore, mansione, numero di lavoratori e stato dell’eventuale procedura.',
    'Quote, scadenze, requisiti e modalità saranno verificati con Conflavoro. La richiesta di contatto non costituisce una domanda di nulla osta.'),
  p89: entry('Anagrafiche, presenze e attività HR in un unico strumento',
    'Conflavoro HR è una piattaforma che collega gestione del personale, recruiting, presenze e scadenze della sicurezza. Le funzionalità AI presentate nel portale supportano l’importazione dei dati e l’analisi delle informazioni, mantenendo le decisioni in capo al team HR.',
    'PMI e responsabili del personale che vogliono organizzare dati, attività e scadenze dei collaboratori.',
    [['Recruiting e anagrafiche', 'Importazione di dati e CV e strumenti di supporto all’esame dei profili.'], ['Presenze e ferie', 'Funzioni per timbrature in sede e lavoro a distanza, con gestione delle richieste.'], ['Scadenze HSE', 'Quadro di corsi, visite, DPI e altri adempimenti, con avvisi e documentazione collegata.']],
    'Indica numero di dipendenti, modalità di lavoro e strumenti HR già utilizzati.'),
  p108: entry('Organizzare progetti e attività anche con la voce',
    'La piattaforma Conflavoro AI Project Manager utilizza l’assistente FALCO per creare e gestire progetti, attività e riunioni attraverso richieste in italiano. La proposta riunisce documenti, collaborazione e funzioni di supporto AI all’interno dei progetti.',
    'PMI, responsabili e gruppi di lavoro che devono coordinare attività e informazioni condivise.',
    [['Attività e assegnazioni', 'Creazione di progetti e task, assegnazione di responsabilità e gestione di avvisi e commenti.'], ['Riunioni', 'Videoconferenze con inviti, trascrizioni e riepiloghi da collegare al progetto.'], ['Documenti interrogabili', 'Una base di conoscenza alimentata dai materiali caricati per cercare informazioni nel contesto del lavoro.']],
    'Descrivi il numero di collaboratori, i progetti gestiti e le attività che vuoi semplificare.'),
  p39: entry('Personale in somministrazione per esigenze diverse',
    'e-work offre somministrazione del lavoro a tempo determinato e indeterminato. Il partner affianca l’impresa nella definizione del fabbisogno e si occupa di selezione, assunzione e gestione retributiva dei lavoratori che svolgono l’attività presso l’azienda utilizzatrice.',
    'Imprese con picchi di lavoro, esigenze stagionali o progetti di inserimento tramite somministrazione.',
    [['Tempo determinato', 'Una soluzione da valutare per esigenze operative circoscritte.'], ['Staff leasing', 'Somministrazione a tempo indeterminato con consulenza sulla gestione delle risorse.'], ['Gestione amministrativa', 'Supporto agli aspetti contrattuali, retributivi e operativi previsti nel servizio.']],
    'Indica mansioni, numero di persone, sede e durata prevista del fabbisogno.',
    'Forma contrattuale e condizioni dell’operazione devono essere verificate dal partner.'),
  p21: entry('Diventare delegato per le dimissioni telematiche',
    'La proposta EBIASP è dedicata ai professionisti che intendono diventare delegati per gestire le dimissioni telematiche. Il portale presenta l’accesso a un gestionale dedicato e l’assistenza dell’ente per svolgere il servizio nell’ambito della delega.',
    'Commercialisti, centri di formazione e professionisti interessati a verificare i requisiti per diventare delegati EBIASP.',
    [['Percorso di delega', 'Confronto con l’ente per approfondire requisiti e modalità di accesso.'], ['Gestionale dedicato', 'Uno strumento per organizzare le procedure relative alle dimissioni dei lavoratori.'], ['Assistenza dell’ente', 'Supporto operativo collegato allo svolgimento del servizio da parte dei delegati.']],
    'Indica la tua attività professionale e l’interesse a diventare delegato.',
    'Questa offerta riguarda l’attivazione del servizio per professionisti. Il modulo non invia le dimissioni di un lavoratore.'),
  p42: entry('Capire competenze, collaborazione e clima aziendale',
    'e-work propone assessment e analisi del clima per aiutare l’azienda a conoscere meglio le proprie risorse umane. Il servizio raccoglie elementi sulle competenze, sulle dinamiche di gruppo e sul coinvolgimento dei dipendenti, per individuare aree di miglioramento.',
    'Imprese che vogliono valorizzare i talenti, migliorare la collaborazione o approfondire il benessere organizzativo.',
    [['Assessment di gruppo', 'Test e simulazioni per osservare collaborazione, comunicazione e potenziale dei team.'], ['Assessment individuale', 'Valutazione di competenze tecniche, trasversali e comportamentali.'], ['Clima aziendale', 'Indagini sulla soddisfazione e sul coinvolgimento delle persone per orientare le azioni organizzative.']],
    'Descrivi il team coinvolto, gli obiettivi della valutazione e le criticità osservate.'),
  p52: entry('Percorsi di inclusione e accompagnamento al lavoro',
    'New Ability è la divisione e-work dedicata all’inserimento lavorativo delle persone con disabilità. La proposta combina orientamento, formazione e accompagnamento per costruire un percorso coerente con le competenze, le aspirazioni e le esigenze della persona.',
    'Aziende interessate a percorsi di inclusione lavorativa e persone che vogliono approfondire il supporto offerto da New Ability.',
    [['Orientamento', 'Individuazione dei punti di forza e degli obiettivi professionali.'], ['Formazione', 'Percorsi di sviluppo o riqualificazione delle competenze.'], ['Accompagnamento', 'Supporto alla costruzione di un progetto personalizzato verso l’occupazione.']],
    'Indica se scrivi come azienda o come persona interessata e descrivi l’obiettivo del contatto.'),
  p69: entry('Voce, video, chat e CRM collegati tra loro',
    'A4 Alinea Suite di Altera Four riunisce strumenti di comunicazione e collaborazione per le relazioni interne e con i clienti. Il portale presenta telefonia, videoconferenze, chat e integrazione CRM, insieme a funzioni per analizzare e sintetizzare le interazioni.',
    'Aziende e gruppi commerciali che vogliono coordinare i canali di contatto e le informazioni sui clienti.',
    [['Comunicazione unificata', 'Riunioni, chat, notifiche e widget web per mettere in contatto persone e visitatori.'], ['Integrazione dei dati', 'Collegamento con il CRM e strumenti per seguire chiamate e attività commerciali.'], ['Supporto AI', 'Trascrizioni, sintesi e suggerimenti per organizzare le informazioni emerse dalle conversazioni.']],
    'Indica numero di utenti, strumenti attuali e canali di comunicazione da integrare.'),
  p70: entry('Connettività progettata per la tua sede',
    'Altera Four propone collegamenti dati attraverso fibra, ponte radio e altre tecnologie, con una valutazione dedicata alla sede. L’offerta A4 Fly Connection comprende soluzioni di backup, monitoraggio e assistenza per le esigenze di continuità operativa.',
    'Imprese e attività che cercano una connessione adeguata, anche in sedi con copertura complessa.',
    [['Analisi della sede', 'Valutazione delle tecnologie e della soluzione utilizzabile nel luogo di installazione.'], ['Backup e controllo', 'Approfondimento dei collegamenti di riserva e del monitoraggio da remoto.'], ['Assistenza', 'La scheda presenta ticketing e supporto continuativo tramite canali dedicati.']],
    'Indica l’indirizzo della sede, il collegamento attuale e i problemi riscontrati.',
    'Copertura, tempi, prestazioni e livelli di servizio vanno confermati sulla sede e sull’offerta.'),
  p74: entry('Presentare l’azienda e incontrare candidati attraverso i video',
    'JOB TV è una piattaforma che utilizza contenuti video per raccontare persone, ruoli e realtà aziendali. Il servizio combina presentazione dell’impresa, profilazione dei candidati e strumenti di incontro tra competenze e opportunità di lavoro.',
    'Aziende che cercano candidati e vogliono affiancare ai curricula una modalità di presentazione più diretta.',
    [['Video e presentazione', 'Contenuti per mostrare il lavoro e le caratteristiche della realtà aziendale.'], ['Profili e abbinamenti', 'Strumenti per mettere in relazione competenze, esperienze e ruoli ricercati.'], ['Formazione mirata', 'La proposta comprende percorsi collegati al profilo e alle esigenze dell’inserimento.']],
    'Indica i ruoli ricercati, la sede e le competenze che servono alla tua attività.'),
  p88: entry('Un assistente digitale per la preparazione del DVR',
    'Conflavoro AI CRM-DVR è una piattaforma per studi e consulenti della sicurezza che supporta la redazione del Documento di Valutazione dei Rischi. Le funzioni AI aiutano a importare e organizzare dati e a predisporre sezioni del documento, con revisione e approvazione professionale.',
    'Studi di consulenza HSE e consulenti RSPP che gestiscono documenti e dati di più aziende.',
    [['Importazione dei dati', 'Gestione di fogli, documenti e scansioni, con riconoscimento dei dati e dei duplicati.'], ['Percorso guidato', 'Sezioni per anagrafica, organigramma, ciclo lavorativo, pericoli, rischi e misure.'], ['Revisione e documenti', 'Passaggi di verifica e approvazione, tracciamento delle attività e produzione di file Word e PDF.']],
    'Indica quante aziende segui, come gestisci oggi i dati e quali fasi vuoi semplificare.',
    'La valutazione dei rischi e la responsabilità professionale restano in capo alle figure competenti.'),
  p109: entry('Organizzare la formazione in aula virtuale',
    'Conflavoro AI VCS integra videoconferenza e strumenti per la gestione della formazione sulla sicurezza sul lavoro. Il portale presenta funzioni per organizzare corsi, docenti, presenze, verifiche di apprendimento e documentazione, con supporto AI alle attività d’aula.',
    'Enti di formazione e professionisti che erogano corsi e vogliono gestire in modo coordinato l’aula virtuale.',
    [['Gestione formativa', 'Strumenti per qualificazione dei docenti, progetto del corso e tracciamento delle attività.'], ['Supporto in aula', 'Assistenza al docente, trascrizioni e riepiloghi delle lezioni.'], ['Verifiche e attestati', 'Gestione dei quiz, segnalazione di anomalie e strumenti per la produzione e verifica degli attestati.']],
    'Indica corsi erogati, numero di partecipanti e modalità di formazione attuali.',
    'Modalità ammesse e validità del percorso devono essere verificate per ciascun corso e contesto formativo.'),
  p110: entry('Dalle informazioni del cliente a un preventivo strutturato',
    'Preventivatore AI organizza appunti, email, note vocali e documenti in una proposta economica costruita sul catalogo e sul modello aziendale. Il processo presentato comprende revisione interna, invio al cliente e passaggi successivi all’accettazione.',
    'Imprese e professionisti che preparano preventivi e vogliono organizzare meglio il flusso commerciale.',
    [['Raccolta delle informazioni', 'Utilizzo di trascrizioni, note, email, PDF e schede prodotto come punto di partenza.'], ['Generazione e revisione', 'Preparazione del documento secondo il modello aziendale, con controllo interno prima dell’invio.'], ['Accettazione e contratto', 'Collegamento tra proposta accettata, contratto firmabile e archiviazione del percorso.']],
    'Descrivi come prepari i preventivi, il catalogo utilizzato e gli strumenti di firma già disponibili.'),
  p9: entry('Organizzare corsi, attestati e scadenze della sicurezza',
    'NUBE81 è un gestionale cloud per le attività formative legate alla sicurezza sul lavoro. La proposta permette di centralizzare fascicoli, registri e attestati e di seguire le scadenze delle aziende gestite, mantenendo tracciate le fasi del percorso formativo.',
    'Centri di formazione e operatori che gestiscono documentazione e aggiornamenti formativi per più aziende.',
    [['Archivio formativo', 'Organizzazione dei documenti per renderli reperibili quando servono.'], ['Scadenze', 'Monitoraggio degli adempimenti e avvisi per pianificare gli aggiornamenti.'], ['Tracciabilità', 'Gestione delle informazioni dall’iscrizione al corso alla documentazione finale.']],
    'Indica numero di aziende e corsisti gestiti e modalità attuale di archiviazione.'),
  p64: entry('Affidare all’esterno logistica e servizi operativi',
    'Il Consorzio Nazionale Logistica propone servizi per esternalizzare attività operative che affiancano il lavoro principale dell’impresa. L’offerta comprende magazzino, movimentazione e trasporto merci, insieme a servizi di pulizia e manutenzione.',
    'Imprese che vogliono valutare l’affidamento di attività logistiche o di gestione delle strutture a un operatore esterno.',
    [['Logistica', 'Gestione del magazzino, deposito, movimentazione, imballaggio e trasporto delle merci.'], ['Facility management', 'Pulizie ordinarie e straordinarie, manutenzione delle aree verdi e altri servizi previsti nell’offerta.'], ['Organizzazione e monitoraggio', 'Soluzioni personalizzate e strumenti per seguire le operazioni affidate.']],
    'Indica sede, attività da esternalizzare, volumi e frequenza del servizio richiesto.'),
  p75: entry('Coordinare cantieri, persone e documenti',
    'Edil-Up unisce un gestionale di cantiere a funzioni di incontro e comunicazione tra imprese. La piattaforma permette di organizzare fasi di lavoro, documenti, presenze e budget e di assegnare accessi in base al ruolo dei collaboratori.',
    'Imprese edili e operatori che devono coordinare cantieri e rapporti con collaboratori e altre aziende.',
    [['Dashboard di cantiere', 'Gestione di attività, presenze, budget e materiali informativi da PC e app.'], ['Comunicazione e archivio', 'Chat, notifiche e documenti associati alle fasi o ai cantieri.'], ['Rete di imprese', 'Profili aziendali, ricerca per zona e categoria e annunci di ricerca o offerta di collaborazione.']],
    'Indica quanti cantieri gestisci, chi deve accedere e quali informazioni vuoi condividere.'),
  p17: entry('Documenti, formazione e prevenzione per l’attività',
    'La scheda Conflavoro presenta servizi di igiene e sicurezza sul lavoro con supporto tecnico alle esigenze dell’azienda. L’offerta copre valutazione dei rischi, documentazione, formazione e verifiche, con interventi da individuare in base all’attività svolta.',
    'Imprese che devono organizzare o aggiornare la gestione della sicurezza, comprese attività alimentari e cantieri.',
    [['Rischi e documenti', 'DVR, DUVRI, rischi specifici, piani di emergenza e documentazione per i cantieri.'], ['Formazione e salute', 'Percorsi per le figure della sicurezza e coordinamento delle esigenze di sorveglianza sanitaria.'], ['Ambiti specialistici', 'HACCP, audit, segnaletica e assistenza tecnica in occasione delle verifiche.']],
    'Indica settore, lavoratori, sedi e documenti o corsi che devi aggiornare.',
    'Il partner definirà gli adempimenti e le prestazioni pertinenti alla tua attività.'),
  p8: entry('Approfondire il servizio di rappresentanza territoriale',
    'OPNASP presenta il servizio del Rappresentante dei Lavoratori per la Sicurezza Territoriale, dedicato ai contesti in cui non è presente un RLS interno. Il contatto permette di verificare l’applicabilità del servizio e le modalità con cui viene svolta la rappresentanza dei lavoratori sulla sicurezza.',
    'Aziende che devono approfondire la propria situazione rispetto alla rappresentanza dei lavoratori per la sicurezza.',
    [['Verifica iniziale', 'Esame della situazione dell’impresa e delle condizioni di accesso al servizio territoriale.'], ['Referente qualificato', 'Un interlocutore per le funzioni di rappresentanza previste nell’ambito della sicurezza.'], ['Prevenzione', 'Confronto sui temi della salute e sicurezza dei lavoratori nel contesto aziendale.']],
    'Indica settore, sede, numero di lavoratori e presenza o assenza di un RLS interno.',
    'Ruoli, competenze e condizioni del servizio saranno chiariti con OPNASP.'),
  p25: entry('Costruire un piano di formazione finanziata',
    'Time Vision affianca le aziende nella valutazione dei fondi interprofessionali e nella realizzazione di piani formativi per i dipendenti. Il servizio parte dall’analisi dei fabbisogni e comprende progettazione, aspetti amministrativi e organizzazione della formazione.',
    'Imprese con dipendenti che vogliono verificare le opportunità di finanziamento della formazione.',
    [['Analisi dei fabbisogni', 'Consulenza iniziale per individuare gli obiettivi e il fondo da approfondire.'], ['Progetto e documentazione', 'Preparazione del piano e gestione delle attività burocratiche collegate.'], ['Percorsi personalizzati', 'Formazione in aula, online o presso la sede aziendale, secondo il progetto applicabile.']],
    'Indica numero di dipendenti, competenze da sviluppare ed eventuale fondo cui l’azienda aderisce.',
    'Finanziabilità, copertura dei costi e condizioni dipendono dal fondo e dal progetto approvato.'),
  p27: entry('Integrare lavoro e formazione nell’apprendistato',
    'Time Vision propone assistenza per i percorsi di apprendistato professionalizzante. Il supporto collega l’inserimento della risorsa a un piano formativo coerente con le esigenze aziendali, organizzando attività pratiche e formazione teorica.',
    'Aziende che intendono inserire apprendisti e vogliono approfondire il percorso formativo e gli adempimenti.',
    [['Piano personalizzato', 'Definizione delle competenze da sviluppare e organizzazione del calendario formativo.'], ['Formazione digitale', 'Contenuti trasversali e possibilità di aule virtuali e lezioni in diretta.'], ['Supporto all’impresa', 'Approfondimento delle condizioni di attivazione e delle agevolazioni applicabili.']],
    'Indica mansione, sede e stato del progetto di inserimento dell’apprendista.',
    'Requisiti, obblighi formativi e benefici contributivi vanno verificati con il partner.'),
  p26: entry('Attivare un percorso formativo in azienda',
    'Time Vision offre supporto per l’attivazione e la gestione di tirocini extracurriculari, dalla ricerca del profilo alle attività amministrative. Il percorso consente di sviluppare competenze in un contesto lavorativo concreto, con un progetto da definire in base alle regole territoriali.',
    'Aziende interessate a ospitare tirocinanti: il portale indica Campania, Puglia, Lazio e Lombardia.',
    [['Ricerca del profilo', 'Analisi delle competenze necessarie e selezione dei candidati da valutare.'], ['Attivazione', 'Gestione delle convenzioni, della documentazione e delle coperture previste.'], ['Percorso in azienda', 'Organizzazione dell’esperienza formativa collegata alle esigenze dell’attività.']],
    'Indica Regione, mansione formativa, sede e periodo previsto.',
    'Disponibilità territoriale, requisiti, durata e costi saranno verificati sul caso specifico.'),
  p78: entry('Lingue straniere per il lavoro del tuo team',
    'European School propone percorsi linguistici aziendali costruiti sugli obiettivi dei collaboratori. La formazione parte dalla valutazione del livello e utilizza esercitazioni pratiche e linguaggio specialistico, con orari e monte ore da concordare.',
    'Aziende che vogliono migliorare le competenze linguistiche del personale per clienti, fornitori o attività internazionali.',
    [['Percorso su misura', 'Test iniziale, lezioni individuali o piccoli gruppi e contenuti legati al lavoro.'], ['Lingue e modalità', 'Corsi online e in presenza in lingue europee ed extraeuropee, da scegliere con il partner.'], ['Obiettivi del corso', 'Sviluppo delle competenze e preparazione agli esami, con attestato di frequenza del percorso.']],
    'Indica lingua, numero di partecipanti, livello di partenza e situazioni professionali da affrontare.',
    'La preparazione a un esame e l’attestato di frequenza non equivalgono al conseguimento automatico di una certificazione linguistica.'),
  p80: entry('Lezioni individuali per i tuoi obiettivi linguistici',
    'European School offre corsi personalizzati per migliorare una lingua, prepararsi agli esami o affrontare studio e lavoro all’estero. Il percorso prevede lezioni individuali con docenti qualificati e un’organizzazione flessibile, anche interamente online.',
    'Persone interessate a sviluppare le competenze linguistiche per studio, lavoro, viaggi o preparazione alle certificazioni.',
    [['Obiettivi personali', 'Contenuti e ritmo del corso da costruire in base alle esigenze dell’allievo.'], ['Docenti e modalità', 'Lezioni con insegnanti madrelingua o bilingui e monte ore personalizzabile.'], ['Percorso ed esami', 'Preparazione linguistica, eventuale preparazione agli esami e attestato di frequenza finale.']],
    'Indica lingua, livello attuale, obiettivo e disponibilità oraria.',
    'L’eventuale certificazione internazionale richiede il percorso e l’esame previsti dall’ente certificatore.'),
  p91: entry('Allenare comunicazione, leadership e capacità commerciali',
    'Dale Carnegie propone percorsi per professionisti e team aziendali basati su esercitazioni e situazioni di lavoro reali. Le classi a posti limitati permettono di lavorare sulle capacità personali con coaching e feedback durante le attività.',
    'Professionisti, manager e aziende che vogliono sviluppare competenze relazionali e organizzative.',
    [['Comunicazione e public speaking', 'Percorsi per le relazioni interpersonali e la preparazione e conduzione di presentazioni.'], ['Leadership', 'Formazione per nuovi manager e responsabili con esperienza, orientata alla guida dei collaboratori.'], ['Vendita relazionale', 'Competenze per costruire fiducia con i clienti e gestire le trattative.']],
    'Indica competenze da sviluppare, numero di partecipanti e ruolo professionale.'),
  p33: entry('Carte carburante e controllo dei rifornimenti',
    'La convenzione Q8 presenta strumenti per il pagamento del carburante e la gestione dei rifornimenti. L’offerta comprende CartissimaQ8 e soluzioni prepagate RecardQ8, con modalità diverse per organizzare spesa, fatturazione e utilizzo.',
    'Imprese e professionisti che vogliono gestire i rifornimenti dei veicoli o valutare buoni carburante.',
    [['CartissimaQ8', 'Carta con fatturazione elettronica e gestione delle transazioni e dei consumi attraverso CartissimaWeb.'], ['RecardQ8', 'Soluzioni prepagate e ricaricabili per utilizzo aziendale e iniziative di incentivazione.'], ['Report e controllo', 'Strumenti per seguire la spesa della flotta e analizzare l’utilizzo delle carte.']],
    'Indica numero di veicoli, spesa indicativa e preferenza tra carta e prepagato.',
    'Sconti, requisiti, modalità di pagamento e condizioni saranno confermati dal partner.'),
  p34: entry('Approfondire la convenzione per l’utilizzo della musica',
    'La convenzione Conflavoro–SIAE prevede condizioni dedicate agli associati per gli utilizzi coperti dall’accordo. La scheda si rivolge ad attività che diffondono musica o altri contenuti protetti e descrive la documentazione associativa da presentare per richiedere l’applicazione della convenzione.',
    'Strutture ricettive, esercizi commerciali, attività professionali e pubblici esercizi interessati agli utilizzi convenzionati.',
    [['Attività interessate', 'Alberghi, B&B, negozi, studi, bar, ristoranti e altre categorie indicate nell’accordo.'], ['Documentazione associativa', 'La procedura prevede una dichiarazione di appartenenza a Conflavoro da richiedere alla struttura territoriale.'], ['Richiesta a SIAE', 'La documentazione deve essere presentata secondo le modalità previste per l’applicazione dello sconto.']],
    'Indica la categoria dell’attività, l’utilizzo della musica e la situazione associativa.',
    'Tariffe, percentuali, utilizzi ammessi e validità della convenzione devono essere confermati prima del pagamento.'),
  p35: entry('Condizioni dedicate per auto e veicoli commerciali',
    'La convenzione tra Conflavoro e Stellantis permette agli associati di approfondire condizioni di acquisto per una selezione di veicoli. Il portale richiama un listino di sconti mensili e la presentazione della tessera associativa presso la rete prevista.',
    'Aziende associate interessate ad acquistare un’auto o un veicolo commerciale per la propria attività.',
    [['Marchi e modelli', 'La scheda presenta veicoli Fiat, Lancia, Alfa Romeo, Jeep e Fiat Professional.'], ['Esigenze di mobilità', 'Possibilità di valutare autovetture e mezzi per il trasporto professionale.'], ['Verifica dell’offerta', 'Consultazione delle condizioni del mese e confronto con la concessionaria sui modelli interessati.']],
    'Indica marca o categoria, uso del mezzo e tempi previsti per l’acquisto.',
    'Sconti, modelli inclusi, disponibilità e requisiti associativi variano e devono essere confermati prima dell’ordine.'),
  p36: entry('Ricevere pagamenti elettronici in sede e in mobilità',
    'La convenzione SumUp presenta lettori portatili per incassare con carte e dispositivi digitali. La proposta è rivolta agli associati Conflavoro che vogliono valutare strumenti di pagamento per il punto vendita o per attività svolte fuori sede.',
    'Negozi, attività di ristorazione e professionisti che devono ricevere pagamenti elettronici.',
    [['Lettori senza fili', 'Dispositivi portatili per gli incassi nel locale o durante il lavoro in mobilità.'], ['Pagamenti digitali', 'Accettazione di pagamenti con carta, smartphone e smartwatch secondo la compatibilità del dispositivo.'], ['Strumenti di gestione', 'App e funzioni per seguire vendite, statistiche e servizi collegati all’offerta.']],
    'Indica come incassi oggi, l’utilizzo previsto e il volume orientativo dei pagamenti.',
    'Costo del lettore, commissioni, servizi inclusi e tempi di accredito vanno verificati sull’offerta aggiornata.'),
  p37: entry('Presenze e documenti del personale da un’unica app',
    'TC Rileva di Teleconsul consente di gestire le presenze e lo scambio documentale tra azienda e dipendenti. La convenzione presenta un accesso a condizioni dedicate e strumenti utilizzabili da smartphone o tablet, senza richiedere necessariamente dispositivi di timbratura aggiuntivi.',
    'Aziende che vogliono digitalizzare presenze, richieste del personale e distribuzione dei documenti.',
    [['Timbrature', 'Registrazione delle presenze tramite dispositivi mobili e associazione alla sede di lavoro.'], ['Richieste e documenti', 'Giustificativi, trasferte, buste paga e certificazioni consultabili e condivisibili.'], ['Collegamento alle paghe', 'Esportazione dei dati e compatibilità da approfondire con il software paghe utilizzato.']],
    'Indica numero di dipendenti, sedi e programma utilizzato per l’elaborazione delle paghe.',
    'Condizioni della convenzione, integrazioni e configurazione del servizio saranno verificate con il partner.'),
};
